<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>HabiFind — Housing Finder & Information System</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#17202b;--muted:#71808f;--line:#e5e9ed;--paper:#f7f8f6;--white:#fff;--teal:#138d83;--teal-dark:#0b6863;--mint:#dff2ec;--coral:#ec7b5f;--yellow:#f4c96b;--shadow:0 18px 50px rgba(34,52,67,.08)}
        *{box-sizing:border-box} body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px} button,input{font:inherit}button{cursor:pointer;border:0}.app{display:flex;min-height:100vh}.sidebar{width:232px;background:#142a2d;color:#d7e4e3;padding:28px 18px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;color:#fff;font-family:Manrope;font-size:19px;letter-spacing:-.5px;margin:0 12px 45px}.brand-mark{background:var(--teal);width:30px;height:30px;border-radius:9px;display:grid;place-items:center;color:#fff;font-size:17px}.nav-label{text-transform:uppercase;color:#7e9a99;font-size:10px;letter-spacing:1.4px;margin:0 14px 13px}.nav{display:grid;gap:5px}.nav button{background:transparent;color:#acc2c0;text-align:left;padding:12px 14px;border-radius:10px;display:flex;align-items:center;gap:12px}.nav button:hover,.nav button.active{background:#214143;color:#fff}.nav-icon{font-size:16px;width:18px;text-align:center}.sidebar-bottom{margin-top:auto;border-top:1px solid #294547;padding-top:18px}.mini-profile{display:flex;align-items:center;gap:10px;padding:10px 8px;color:#fff}.avatar{width:34px;height:34px;border-radius:50%;background:#f0c4a8;display:grid;place-items:center;color:#57372d;font-weight:700;font-size:12px}.mini-profile small{display:block;color:#8ba6a4;font-size:11px;margin-top:2px}.main{flex:1;padding:0 40px 48px;min-width:0}.topbar{height:80px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.eyebrow{color:var(--teal);font-weight:700;letter-spacing:.6px;font-size:11px;text-transform:uppercase}.top-actions{display:flex;align-items:center;gap:18px}.top-actions button{background:transparent;color:var(--muted);font-size:19px}.role-switcher{display:flex;background:#e9edeb;border-radius:9px;padding:3px;gap:2px}.role-switcher button{padding:8px 13px;color:#71808a;background:transparent;border-radius:7px;font-size:12px;font-weight:600}.role-switcher button.active{background:#fff;color:var(--ink);box-shadow:0 2px 8px #cad4d2}.intro{display:flex;justify-content:space-between;align-items:flex-end;padding:38px 0 26px}.intro h1{font:800 34px Manrope;margin:5px 0 8px;letter-spacing:-1.5px}.intro p{color:var(--muted);margin:0}.primary{background:var(--teal);color:#fff;border-radius:9px;padding:12px 18px;font-weight:700;box-shadow:0 8px 16px rgba(19,141,131,.18)}.primary:hover{background:var(--teal-dark)}.secondary{background:#fff;border:1px solid var(--line);color:var(--ink);border-radius:9px;padding:11px 16px;font-weight:700}.search-panel{background:var(--white);padding:18px;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);display:flex;gap:12px;align-items:center}.searchbox{flex:1;border:1px solid var(--line);border-radius:9px;display:flex;align-items:center;padding:0 14px;color:var(--muted)}.searchbox input{border:0;outline:0;width:100%;padding:13px 10px;background:transparent}.filter-chip{padding:10px 13px;border:1px solid var(--line);background:#fff;border-radius:8px;color:#65737d;font-size:12px}.filter-chip.active{border-color:#9ed5ca;background:var(--mint);color:var(--teal-dark);font-weight:700}.section-head{display:flex;justify-content:space-between;align-items:center;margin:31px 0 15px}.section-head h2{font:700 18px Manrope;margin:0;letter-spacing:-.5px}.section-head a{color:var(--teal);font-weight:700;font-size:12px}.user-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.9fr);gap:20px}.listing-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.listing{background:#fff;border:1px solid var(--line);border-radius:13px;overflow:hidden;transition:.2s}.listing:hover{transform:translateY(-2px);box-shadow:var(--shadow)}.listing-image{height:145px;position:relative;background:linear-gradient(135deg,#a7cec7,#527a7a)}.listing:nth-child(2) .listing-image{background:linear-gradient(135deg,#e9b78f,#9f6c61)}.listing:nth-child(3) .listing-image{background:linear-gradient(135deg,#c2c6d8,#757c9d)}.listing:nth-child(4) .listing-image{background:linear-gradient(135deg,#d6bd9c,#89705e)}.listing-image:after{content:'PHOTO PREVIEW';position:absolute;inset:0;display:grid;place-items:center;color:rgba(255,255,255,.7);font-size:10px;letter-spacing:2px}.save{position:absolute;z-index:1;right:10px;top:10px;background:#fff;border-radius:50%;width:31px;height:31px;color:#5e6c73;font-size:17px}.save.saved{color:var(--coral)}.listing-info{padding:14px}.listing-info h3{font-size:14px;margin:0 0 5px}.listing-info p{margin:0;color:var(--muted);font-size:12px}.meta{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.price{font-weight:800;color:var(--teal-dark)}.price span{font-size:11px;color:var(--muted);font-weight:400}.verified{font-size:10px;color:var(--teal);background:var(--mint);padding:5px 7px;border-radius:5px;font-weight:700}.map-card{background:#d8e4df;border-radius:13px;min-height:100%;position:relative;overflow:hidden;padding:17px}.map-card:before,.map-card:after{content:'';position:absolute;background:rgba(255,255,255,.55);height:17px;width:150%;transform:rotate(-32deg);top:38%;left:-30%}.map-card:after{transform:rotate(37deg);top:63%}.map-top{position:relative;z-index:1;background:#fff;padding:10px 12px;border-radius:8px;font-size:12px;box-shadow:0 4px 14px #8aa29a55}.pin{position:absolute;z-index:1;background:var(--coral);color:#fff;width:25px;height:25px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);display:grid;place-items:center;box-shadow:0 3px 9px #87524777}.pin b{transform:rotate(45deg);font-size:10px}.pin.one{top:37%;left:35%}.pin.two{top:53%;left:66%;background:var(--teal)}.pin.three{top:70%;left:47%;background:var(--teal)}.map-legend{position:absolute;z-index:1;bottom:14px;left:14px;right:14px;background:#fff;border-radius:8px;padding:10px;font-size:11px}.map-legend strong{display:block;margin-bottom:3px}.map-legend span{color:var(--muted)}.feature-strip{margin-top:34px;background:#183536;color:#e9f5f1;border-radius:14px;padding:23px 26px;display:flex;justify-content:space-between;align-items:center}.feature-strip h3{font:700 17px Manrope;margin:0 0 5px}.feature-strip p{margin:0;color:#a8c6c1;font-size:12px}.feature-items{display:flex;gap:32px}.feature-item{display:flex;gap:9px;align-items:center;font-size:12px}.feature-icon{width:30px;height:30px;border-radius:8px;background:#2d5754;display:grid;place-items:center;color:#8ee3d1}.dashboard-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.stat{background:#fff;border:1px solid var(--line);border-radius:12px;padding:17px}.stat-top{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.stat-icon{width:28px;height:28px;border-radius:8px;background:var(--mint);display:grid;place-items:center;color:var(--teal)}.stat strong{display:block;font:800 27px Manrope;margin:15px 0 4px}.trend{color:var(--teal);font-size:11px;font-weight:700}.subtle{color:var(--muted);font-size:11px}.panel{background:#fff;border:1px solid var(--line);border-radius:13px;padding:20px}.owner-columns,.admin-columns{display:grid;grid-template-columns:1.25fr .85fr;gap:20px}.panel h3{font:700 15px Manrope;margin:0}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.bars{height:150px;display:flex;align-items:flex-end;gap:12px;border-bottom:1px solid var(--line);padding:0 5px}.bar-wrap{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:7px}.bar{width:100%;max-width:30px;background:#a9dace;border-radius:5px 5px 0 0}.bar.highlight{background:var(--teal)}.bar-label{font-size:10px;color:var(--muted)}.legend-row{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;margin-top:13px}.data-list{display:grid;gap:11px}.data-row{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-bottom:1px solid #edf0ef}.data-row:last-child{border:0}.data-row strong{display:block;font-size:12px}.data-row small{color:var(--muted);font-size:11px}.status{border-radius:5px;padding:5px 8px;font-size:10px;font-weight:700}.status.green{background:var(--mint);color:var(--teal-dark)}.status.orange{background:#fff0d7;color:#a86a16}.status.red{background:#fde4de;color:#b0523c}.queue{display:grid;gap:10px}.queue-card{border:1px solid var(--line);padding:13px;border-radius:9px}.queue-card p{font-size:12px;margin:0 0 9px}.queue-actions{display:flex;gap:7px}.queue-actions button{font-size:11px;padding:7px 10px;border-radius:6px;background:#f3f6f5;color:var(--teal-dark);font-weight:700}.toast{position:fixed;right:25px;bottom:25px;background:#173635;color:#fff;padding:13px 17px;border-radius:9px;box-shadow:var(--shadow);opacity:0;transform:translateY(12px);transition:.25s;pointer-events:none;font-size:12px}.toast.show{opacity:1;transform:translateY(0)}
        @media(max-width:1000px){.sidebar{width:75px;padding:25px 10px}.brand{margin:0 auto 45px}.brand span,.nav-label,.nav button span,.mini-profile div{display:none}.nav button{justify-content:center}.mini-profile{justify-content:center}.main{padding:0 22px 40px}.user-grid,.owner-columns,.admin-columns{grid-template-columns:1fr}.map-card{min-height:270px}.feature-items{gap:15px}}
        @media(max-width:680px){.main{padding:0 14px 30px}.topbar{height:auto;padding:16px 0;align-items:flex-start;gap:12px;flex-direction:column}.role-switcher{width:100%;overflow:auto}.role-switcher button{flex:1;white-space:nowrap}.intro{padding:25px 0 19px;align-items:flex-start;gap:15px;flex-direction:column}.intro h1{font-size:28px}.search-panel{flex-wrap:wrap}.searchbox{min-width:100%}.listing-grid,.dashboard-grid{grid-template-columns:1fr 1fr}.feature-strip{display:block}.feature-items{margin-top:20px;display:grid;grid-template-columns:1fr 1fr}.feature-item{font-size:11px}.stat strong{font-size:22px}.section-head{margin-top:24px}}
    </style>
</head>
<body>
<div class="app">
    <aside class="sidebar">
        <div class="brand"><div class="brand-mark">⌂</div><span>HabiFind</span></div>
        <div class="nav-label">Workspace</div>
        <nav class="nav" aria-label="Main navigation">
            <button class="active"><span class="nav-icon">▦</span><span>Overview</span></button>
            <button><span class="nav-icon">⌕</span><span>Find a home</span></button>
            <button><span class="nav-icon">♡</span><span>Saved homes</span></button>
            <button><span class="nav-icon">▤</span><span>Messages</span></button>
        </nav>
        <div class="nav-label" style="margin-top:30px">Account</div>
        <nav class="nav"><button><span class="nav-icon">⚙</span><span>Settings</span></button><button><span class="nav-icon">?</span><span>Help center</span></button></nav>
        <div class="sidebar-bottom"><div class="mini-profile"><div class="avatar">JD</div><div><strong>Jordan Dela Cruz</strong><small>Student account</small></div></div></div>
    </aside>
    <main class="main">
        <header class="topbar"><div><span class="eyebrow">Interactive prototype · Capstone</span></div><div class="top-actions"><div class="role-switcher" role="tablist" aria-label="Choose dashboard role"><button class="active" data-role="user">User / Student</button><button data-role="owner">Boardinghouse owner</button><button data-role="admin">Admin</button></div><button aria-label="Notifications">♧</button><div class="avatar">JD</div></div></header>
        <section class="screen" id="user-screen">
            <div class="intro"><div><div class="eyebrow">Tuesday, September 17, 2026</div><h1>Find a place to feel at home.</h1><p>Verified boardinghouses near your campus, made simple.</p></div><button class="secondary" data-toast="Your profile preview is ready">View my profile ↗</button></div>
            <div class="search-panel"><div class="searchbox">⌕<input id="listing-search" type="search" placeholder="Search by area, landmark, or boardinghouse"></div><button class="filter-chip active">All homes</button><button class="filter-chip">Under ₱8,000</button><button class="filter-chip">Near campus</button><button class="primary" data-toast="More filters opened">Filters +</button></div>
            <div class="section-head"><h2>Recommended for you</h2><a href="#">View all listings ↗</a></div>
            <div class="user-grid"><div><div class="listing-grid" id="listing-grid"><article class="listing" data-search="greenleaf residences talamban cebu university"><div class="listing-image"><button class="save" aria-label="Save Greenleaf Residences">♡</button></div><div class="listing-info"><h3>Greenleaf Residences</h3><p>Talamban, Cebu City · 0.8 km from campus</p><div class="meta"><span class="price">₱6,500 <span>/ month</span></span><span class="verified">✓ VERIFIED</span></div></div></article><article class="listing" data-search="the nook boarding house banilad cebu"><div class="listing-image"><button class="save" aria-label="Save The Nook Boarding House">♡</button></div><div class="listing-info"><h3>The Nook Boarding House</h3><p>Banilad, Cebu City · 1.2 km from campus</p><div class="meta"><span class="price">₱7,800 <span>/ month</span></span><span class="verified">✓ VERIFIED</span></div></div></article><article class="listing" data-search="maria's place lahug cebu"><div class="listing-image"><button class="save" aria-label="Save Maria's Place">♡</button></div><div class="listing-info"><h3>Maria&apos;s Place</h3><p>Lahug, Cebu City · 1.6 km from campus</p><div class="meta"><span class="price">₱5,900 <span>/ month</span></span><span class="verified">✓ VERIFIED</span></div></div></article><article class="listing" data-search="sunrise homes urgello cebu"><div class="listing-image"><button class="save" aria-label="Save Sunrise Homes">♡</button></div><div class="listing-info"><h3>Sunrise Homes</h3><p>Urgello, Cebu City · 2.1 km from campus</p><div class="meta"><span class="price">₱7,200 <span>/ month</span></span><span class="verified">✓ VERIFIED</span></div></div></article></div></div><div class="map-card"><div class="map-top">⌖ Showing homes around <strong>University of San Carlos</strong></div><div class="pin one"><b>1</b></div><div class="pin two"><b>2</b></div><div class="pin three"><b>3</b></div><div class="map-legend"><strong>18 homes found nearby</strong><span>Tap a pin to preview a listing</span></div></div></div>
            <div class="feature-strip"><div><h3>Housing search, without the guesswork.</h3><p>Every listing is reviewed so you can focus on finding the right fit.</p></div><div class="feature-items"><div class="feature-item"><span class="feature-icon">✓</span>Verified listings</div><div class="feature-item"><span class="feature-icon">⌖</span>Campus proximity</div><div class="feature-item"><span class="feature-icon">♡</span>Save favorites</div></div></div>
        </section>
        <section class="screen" id="owner-screen" hidden>
            <div class="intro"><div><div class="eyebrow">Owner workspace</div><h1>Good morning, Alicia.</h1><p>Here&apos;s how your boardinghouses are doing this month.</p></div><button class="primary" data-toast="New listing form opened">+ Add new listing</button></div>
            <div class="dashboard-grid"><div class="stat"><div class="stat-top">Total listings <span class="stat-icon">▤</span></div><strong>08</strong><span class="trend">↑ 2 this month</span></div><div class="stat"><div class="stat-top">Occupied rooms <span class="stat-icon">⌂</span></div><strong>42 <small class="subtle">/ 56</small></strong><span class="trend">75% occupancy rate</span></div><div class="stat"><div class="stat-top">New inquiries <span class="stat-icon">✉</span></div><strong>14</strong><span class="trend">↑ 18% from last week</span></div><div class="stat"><div class="stat-top">Profile views <span class="stat-icon">◉</span></div><strong>1,284</strong><span class="trend">↑ 12.4% this month</span></div></div>
            <div class="section-head"><h2>Listing performance</h2><button class="filter-chip" data-toast="Date range menu opened">Last 30 days⌄</button></div><div class="owner-columns"><div class="panel"><div class="panel-head"><h3>Listing views</h3><span class="trend">+12.4%</span></div><div class="bars"><div class="bar-wrap"><div class="bar" style="height:42%"></div><span class="bar-label">M</span></div><div class="bar-wrap"><div class="bar" style="height:57%"></div><span class="bar-label">T</span></div><div class="bar-wrap"><div class="bar" style="height:45%"></div><span class="bar-label">W</span></div><div class="bar-wrap"><div class="bar highlight" style="height:76%"></div><span class="bar-label">T</span></div><div class="bar-wrap"><div class="bar" style="height:63%"></div><span class="bar-label">F</span></div><div class="bar-wrap"><div class="bar" style="height:88%"></div><span class="bar-label">S</span></div><div class="bar-wrap"><div class="bar" style="height:71%"></div><span class="bar-label">S</span></div></div><div class="legend-row"><span>Sep 01</span><span>Sep 17, 2026</span></div></div><div class="panel"><div class="panel-head"><h3>Recent inquiries</h3><a class="eyebrow" href="#">View all</a></div><div class="queue"><div class="queue-card"><p><strong>Jordan Dela Cruz</strong> is interested in Greenleaf Residences.</p><div class="queue-actions"><button data-toast="Inquiry marked as replied">Reply</button><button data-toast="Inquiry details opened">View details</button></div></div><div class="queue-card"><p><strong>Sam Rivera</strong> asked about room availability for October.</p><div class="queue-actions"><button data-toast="Inquiry marked as replied">Reply</button><button data-toast="Inquiry details opened">View details</button></div></div></div></div></div>
            <div class="section-head"><h2>Your listings</h2><a href="#">Manage all listings ↗</a></div><div class="panel"><div class="data-list"><div class="data-row"><div><strong>Greenleaf Residences</strong><small>Talamban · 12 rooms · Updated 2 days ago</small></div><span class="status green">Published</span></div><div class="data-row"><div><strong>Sunrise Annex</strong><small>Banilad · 8 rooms · Updated 5 days ago</small></div><span class="status green">Published</span></div><div class="data-row"><div><strong>Alicia&apos;s Place</strong><small>Lahug · 6 rooms · Submitted today</small></div><span class="status orange">Under review</span></div></div></div>
        </section>
        <section class="screen" id="admin-screen" hidden>
            <div class="intro"><div><div class="eyebrow">System administration</div><h1>Good morning, Jordan.</h1><p>Monitor the HabiFind community and keep housing information trusted.</p></div><button class="secondary" data-toast="System report exported">Export report ↓</button></div>
            <div class="dashboard-grid"><div class="stat"><div class="stat-top">Registered users <span class="stat-icon">♙</span></div><strong>2,481</strong><span class="trend">↑ 8.2% this month</span></div><div class="stat"><div class="stat-top">Active listings <span class="stat-icon">⌂</span></div><strong>384</strong><span class="trend">↑ 24 new this week</span></div><div class="stat"><div class="stat-top">Pending reviews <span class="stat-icon">◷</span></div><strong>12</strong><span class="status orange">Needs attention</span></div><div class="stat"><div class="stat-top">Reports resolved <span class="stat-icon">✓</span></div><strong>96.4%</strong><span class="trend">↑ 4.1% resolution rate</span></div></div>
            <div class="section-head"><h2>Moderation center</h2><button class="filter-chip" data-toast="Queue filter opened">All queues⌄</button></div><div class="admin-columns"><div class="panel"><div class="panel-head"><h3>Verification queue</h3><span class="status orange">12 pending</span></div><div class="data-list"><div class="data-row"><div><strong>Greenleaf Residences</strong><small>Boardinghouse listing · Submitted 24 min ago</small></div><div class="queue-actions"><button data-toast="Listing approved">Approve</button><button data-toast="Listing details opened">Review</button></div></div><div class="data-row"><div><strong>Harbor View Dormitory</strong><small>Owner verification · Submitted 1 hr ago</small></div><div class="queue-actions"><button data-toast="Owner approved">Approve</button><button data-toast="Verification details opened">Review</button></div></div><div class="data-row"><div><strong>Cityscape Rooms</strong><small>Boardinghouse listing · Submitted 3 hrs ago</small></div><div class="queue-actions"><button data-toast="Listing approved">Approve</button><button data-toast="Listing details opened">Review</button></div></div></div></div><div class="panel"><div class="panel-head"><h3>System health</h3><span class="status green">All systems live</span></div><div class="data-list"><div class="data-row"><div><strong>Listing search</strong><small>Response time 182ms</small></div><span class="status green">Operational</span></div><div class="data-row"><div><strong>Image moderation</strong><small>Last checked 2 min ago</small></div><span class="status green">Operational</span></div><div class="data-row"><div><strong>Report resolution</strong><small>4 open reports</small></div><span class="status orange">Monitoring</span></div></div><button class="secondary" style="width:100%;margin-top:15px" data-toast="Activity log opened">View activity log</button></div></div>
            <div class="section-head"><h2>Recent activity</h2><a href="#">View audit log ↗</a></div><div class="panel"><div class="data-list"><div class="data-row"><div><strong>Listing approved</strong><small>Greenleaf Residences was approved by you</small></div><small>24 min ago</small></div><div class="data-row"><div><strong>New report received</strong><small>A user reported inaccurate pricing on Cityscape Rooms</small></div><small>1 hr ago</small></div><div class="data-row"><div><strong>New owner registered</strong><small>Alicia Santos created a boardinghouse owner account</small></div><small>2 hrs ago</small></div></div></div>
        </section>
    </main>
</div>
<div class="toast" id="toast" role="status"></div>
<script>
(function(){
 const tabs=document.querySelectorAll('[data-role]'); const screens={user:document.getElementById('user-screen'),owner:document.getElementById('owner-screen'),admin:document.getElementById('admin-screen')};
 tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(item=>item.classList.remove('active'));tab.classList.add('active');Object.values(screens).forEach(screen=>screen.hidden=true);screens[tab.dataset.role].hidden=false;document.querySelector('.eyebrow').textContent=tab.dataset.role==='user'?'Interactive prototype · Capstone':'Interactive prototype · Role preview';}));
 document.querySelectorAll('.filter-chip').forEach(chip=>{if(!chip.dataset.toast)chip.addEventListener('click',()=>chip.classList.toggle('active'));});
 const search=document.getElementById('listing-search'); search.addEventListener('input',()=>{const query=search.value.toLowerCase();document.querySelectorAll('.listing').forEach(card=>card.style.display=card.dataset.search.includes(query)?'':'none');});
 document.querySelectorAll('.save').forEach(button=>button.addEventListener('click',()=>{button.classList.toggle('saved');button.textContent=button.classList.contains('saved')?'♥':'♡';showToast(button.classList.contains('saved')?'Listing saved to your favorites':'Listing removed from favorites');}));
 function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),2200)}
 document.querySelectorAll('[data-toast]').forEach(button=>button.addEventListener('click',()=>showToast(button.dataset.toast)));
})();
</script>
</body>
</html>
